extends Node3D
class_name TunisCommercePass

var generated_count := 0
var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_corner_fruit_stand()
    _build_sidewalk_kiosk()
    _build_hanging_shop_signs()
    _build_bread_crates()
    apply_visual_budget(current_detail_level)

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    var show_medium := current_detail_level >= 1
    var show_high := current_detail_level >= 2
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_medium
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_high

func _register_detail(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
    return node

func _material(color: Color, roughness := 0.82, metallic := 0.0) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = roughness
    material.metallic = metallic
    return material

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _sphere(parent: Node3D, pos: Vector3, radius: float, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := SphereMesh.new()
    mesh.radius = radius
    mesh.height = radius * 2.0
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _build_corner_fruit_stand() -> void:
    var root := Node3D.new()
    root.name = "CornerFruitStand"
    root.position = Vector3(56.5, 0.0, -8.2)
    add_child(root)

    _box(root, Vector3(0, 0.42, 0), Vector3(4.8, 0.82, 1.5), Color("#8b613b"))
    _box(root, Vector3(0, 2.45, -0.52), Vector3(5.4, 0.16, 2.25), Color("#d5b24b"))
    for x in [-1.8, -0.6, 0.6, 1.8]:
        _box(root, Vector3(x, 1.35, -0.52), Vector3(0.09, 2.6, 0.09), Color("#5f5144"))

    var produce_colors := [Color("#d18b2c"), Color("#c34d3f"), Color("#6e964b")]
    for row in range(2):
        for col in range(6):
            var item := _sphere(root, Vector3(-1.65 + col * 0.66, 0.98 + row * 0.28, -0.15), 0.18, produce_colors[(row + col) % produce_colors.size()])
            _register_detail(item, 2)

func _build_sidewalk_kiosk() -> void:
    var root := Node3D.new()
    root.name = "SidewalkKiosk"
    root.position = Vector3(-18.5, 0.0, 53.8)
    add_child(root)

    _box(root, Vector3(0, 1.1, 0), Vector3(3.2, 2.2, 2.0), Color("#48605d"))
    _box(root, Vector3(0, 2.32, -0.1), Vector3(3.6, 0.22, 2.35), Color("#d5d0bf"))
    _box(root, Vector3(0, 1.22, -1.05), Vector3(2.2, 0.92, 0.08), Color("#202d31"))
    _label(root, Vector3(0, 2.02, -1.11), "كشك", 0.008)

    for x in [-0.9, -0.3, 0.3, 0.9]:
        var display := _box(root, Vector3(x, 1.2, -1.13), Vector3(0.34, 0.5, 0.06), Color("#d8b947"))
        _register_detail(display, 2)

func _build_hanging_shop_signs() -> void:
    var signs := [
        {"p": Vector3(-45.5, 3.35, -65.0), "t": "مقهى"},
        {"p": Vector3(27.0, 3.45, -65.0), "t": "مواد غذائية"},
        {"p": Vector3(76.8, 3.25, -8.4), "t": "خبز"}
    ]
    for entry in signs:
        var root := Node3D.new()
        root.position = entry["p"]
        add_child(root)
        _register_detail(root, 1)
        _box(root, Vector3.ZERO, Vector3(1.95, 0.82, 0.10), Color("#2f4c62"))
        _box(root, Vector3(0.98, 0.0, 0.0), Vector3(0.18, 0.18, 0.72), Color("#44484a"))
        _label(root, Vector3(0, 0, -0.08), str(entry["t"]), 0.0055)

func _build_bread_crates() -> void:
    var root := Node3D.new()
    root.name = "BreadCrates"
    root.position = Vector3(74.2, 0.0, -10.2)
    add_child(root)
    _register_detail(root, 1)

    for col in range(3):
        _box(root, Vector3(col * 0.72, 0.35, 0), Vector3(0.62, 0.62, 0.82), Color("#92663d"))
        for row in range(2):
            var loaf := _box(root, Vector3(col * 0.72, 0.74 + row * 0.17, -0.02), Vector3(0.42, 0.12, 0.62), Color("#d7a55b"))
            _register_detail(loaf, 2)

func _label(parent: Node3D, pos: Vector3, text: String, pixel: float) -> void:
    var label := Label3D.new()
    label.position = pos
    label.text = text
    label.font_size = 48
    label.pixel_size = pixel
    label.outline_size = 6
    label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
    parent.add_child(label)
    generated_count += 1

extends Node3D
class_name TunisDailyRhythmPass

var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var morning_nodes: Array[Node3D] = []
var daytime_nodes: Array[Node3D] = []
var evening_nodes: Array[Node3D] = []
var current_detail_level := 2
var clock: WorldClock

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_morning_market()
    _build_daytime_delivery_activity()
    _build_evening_cafe_activity()
    apply_visual_budget(current_detail_level)
    _refresh_time_state()

func configure(world_clock: WorldClock) -> void:
    clock = world_clock
    if clock != null and not clock.minute_changed.is_connected(_on_minute_changed):
        clock.minute_changed.connect(_on_minute_changed)
    _refresh_time_state()

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = current_detail_level >= 1
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = current_detail_level >= 2
    _refresh_time_state()

func _register(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
    return node

func _mat(color: Color) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = 0.9
    return material

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var node := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    node.mesh = mesh
    node.position = pos
    node.material_override = _mat(color)
    parent.add_child(node)
    return node

func _build_morning_market() -> void:
    var root := Node3D.new()
    root.name = "MorningMarketActivity"
    add_child(root)
    _register(root, 1)
    morning_nodes.append(root)
    for x in [-39.0, -35.0, -31.0]:
        _box(root, Vector3(x, 0.48, -52.5), Vector3(2.6, 0.9, 1.2), Color("#8f6845"))
        _box(root, Vector3(x, 1.08, -52.5), Vector3(2.3, 0.18, 1.0), Color("#d7b33e"))

func _build_daytime_delivery_activity() -> void:
    var root := Node3D.new()
    root.name = "DaytimeDeliveryActivity"
    add_child(root)
    _register(root, 2)
    daytime_nodes.append(root)
    for z in [-72.0, -69.8, -67.6]:
        _box(root, Vector3(41.5, 0.42, z), Vector3(1.15, 0.82, 1.15), Color("#6f5a43"))
    _box(root, Vector3(43.0, 0.75, -69.8), Vector3(0.12, 1.5, 0.9), Color("#454545"))

func _build_evening_cafe_activity() -> void:
    var root := Node3D.new()
    root.name = "EveningCafeActivity"
    add_child(root)
    _register(root, 1)
    evening_nodes.append(root)
    for x in [-55.0, -51.5, -48.0, -44.5]:
        _box(root, Vector3(x, 0.38, -60.8), Vector3(0.85, 0.08, 0.85), Color("#5d4030"))
        _box(root, Vector3(x, 0.72, -60.8), Vector3(0.09, 0.65, 0.09), Color("#454545"))

func _on_minute_changed(_day: int, _hour: int, _minute: int) -> void:
    _refresh_time_state()

func _refresh_time_state() -> void:
    var hour := 12
    if clock != null:
        hour = clock.current_hour()
    var morning_active := hour >= 6 and hour < 11
    var daytime_active := hour >= 9 and hour < 17
    var evening_active := hour >= 17 and hour < 23
    _set_phase_visibility(morning_nodes, morning_active)
    _set_phase_visibility(daytime_nodes, daytime_active)
    _set_phase_visibility(evening_nodes, evening_active)

func _set_phase_visibility(nodes: Array[Node3D], active: bool) -> void:
    for node in nodes:
        if not is_instance_valid(node):
            continue
        var detail_allowed := true
        if node in medium_detail_nodes:
            detail_allowed = current_detail_level >= 1
        elif node in high_detail_nodes:
            detail_allowed = current_detail_level >= 2
        node.visible = active and detail_allowed

extends Node3D
class_name TunisFacadePass

var generated_count := 0

func build() -> void:
    var shells = [
        {"p":Vector3(-85,0,-85), "w":18.0, "h":13.0, "d":18.0},
        {"p":Vector3(-30,0,-85), "w":22.0, "h":16.0, "d":21.0},
        {"p":Vector3(30,0,-85), "w":19.0, "h":12.0, "d":20.0},
        {"p":Vector3(85,0,-85), "w":23.0, "h":17.0, "d":19.0},
        {"p":Vector3(-85,0,-30), "w":21.0, "h":15.0, "d":22.0},
        {"p":Vector3(30,0,-30), "w":20.0, "h":14.0, "d":18.0},
        {"p":Vector3(85,0,-30), "w":22.0, "h":16.0, "d":21.0},
        {"p":Vector3(-30,0,30), "w":19.0, "h":13.0, "d":19.0},
        {"p":Vector3(30,0,30), "w":22.0, "h":17.0, "d":21.0},
        {"p":Vector3(85,0,30), "w":20.0, "h":15.0, "d":20.0}
    ]
    for i in range(shells.size()):
        _decorate_front(shells[i], i)

func _decorate_front(entry: Dictionary, idx: int) -> void:
    var center: Vector3 = entry["p"]
    var width := float(entry["w"])
    var height := float(entry["h"])
    var depth := float(entry["d"])
    var front_z := center.z - depth * 0.5 - 0.08

    # Roof parapet.
    _box(Vector3(center.x, height + 0.45, front_z + 0.3), Vector3(width * 0.94, 0.55, 0.42), Color("#d6c8b0"))

    # Storefront and awning.
    var shop_color := Color("#2d373d") if idx % 2 == 0 else Color("#4a3428")
    _box(Vector3(center.x, 1.45, front_z - 0.06), Vector3(width * 0.72, 2.5, 0.18), shop_color)

    var awning_color := Color("#9d3e37") if idx % 3 == 0 else Color("#2f596b")
    var awning := _box(
        Vector3(center.x, 2.85, front_z - 0.65),
        Vector3(width * 0.70, 0.16, 1.35),
        awning_color
    )
    awning.rotation_degrees.x = -9.0

    var floors := maxi(2, int(height / 3.2))
    for floor in range(1, floors):
        var y := 3.0 + floor * 2.75
        for xo_value in [-0.32, 0.0, 0.32]:
            var xo: float = float(xo_value)
            var x: float = center.x + width * xo
            _box(Vector3(x, y, front_z - 0.05), Vector3(1.65, 1.55, 0.13), Color("#325264"))
            _box(Vector3(x - 1.00, y, front_z - 0.10), Vector3(0.32, 1.72, 0.12), Color("#477257"))
            _box(Vector3(x + 1.00, y, front_z - 0.10), Vector3(0.32, 1.72, 0.12), Color("#477257"))
            if (floor + idx) % 2 == 0:
                _balcony(Vector3(x, y - 0.78, front_z - 0.70), 2.55)

        # AC unit.
        if floor % 2 == 1:
            _box(
                Vector3(center.x + width * 0.38, y - 0.25, front_z - 0.32),
                Vector3(1.15, 0.72, 0.46),
                Color("#c8c7c0")
            )

func _balcony(pos: Vector3, width: float) -> void:
    _box(pos, Vector3(width, 0.12, 0.85), Color("#d7cfbe"))
    _box(pos + Vector3(0,0.62,-0.36), Vector3(width, 0.06, 0.06), Color("#24292c"))
    for x_value in [-0.42, -0.21, 0.0, 0.21, 0.42]:
        var x: float = float(x_value)
        _box(
            pos + Vector3(width * x, 0.34, -0.36),
            Vector3(0.045, 0.68, 0.045),
            Color("#24292c")
        )

func _box(pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var mi := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    mi.mesh = mesh
    mi.position = pos
    var mat := StandardMaterial3D.new()
    mat.albedo_color = color
    mat.roughness = 0.84
    mi.material_override = mat
    add_child(mi)
    generated_count += 1
    return mi
